namespace cmap
{
    std::map<int, std::string> list()
    {
        std::map<int, std::string> map{};

        for (int i = 0; i <= static_cast<int>(colormap_t::DEEPGREEN); ++i) {
            map[i] = to_string(static_cast<colormap_t>(i));
        }

        return map;
    }

    std::tuple<uint8_t, uint8_t, uint8_t> lookup(colormap_t map, const uint8_t gray)
    {
        const auto idx = static_cast<uint8_t>(map) * 1024 + gray * 4;
        return { LUT[idx + 0], LUT[idx + 1], LUT[idx + 2] };
    }

    const uint8_t *lut(colormap_t cmap) { return LUT + static_cast<uint8_t>(cmap) * 1024; }

    const char *to_string(const colormap_t cmap)
    {
        switch (cmap) {

        case colormap_t::AUTUMN:           return "AUTUMN";
        case colormap_t::BONE:             return "BONE";
        case colormap_t::JET:              return "JET";
        case colormap_t::WINTER:           return "WINTER";
        case colormap_t::RAINBOW:          return "RAINBOW";
        case colormap_t::OCEAN:            return "OCEAN";
        case colormap_t::SUMMER:           return "SUMMER";
        case colormap_t::SPRING:           return "SPRING";
        case colormap_t::COOL:             return "COOL";
        case colormap_t::HSV:              return "HSV";
        case colormap_t::PINK:             return "PINK";
        case colormap_t::HOT:              return "HOT";
        case colormap_t::PARULA:           return "PARULA";
        case colormap_t::MAGMA:            return "MAGMA";
        case colormap_t::INFERNO:          return "INFERNO";
        case colormap_t::PLASMA:           return "PLASMA";
        case colormap_t::VIRIDIS:          return "VIRIDIS";
        case colormap_t::CIVIDIS:          return "CIVIDIS";
        case colormap_t::TWILIGHT:         return "TWILIGHT";
        case colormap_t::TWILIGHT_SHIFTED: return "TWILIGHT_SHIFTED";
        case colormap_t::TURBO:            return "TURBO";
        case colormap_t::DEEPGREEN:        return "DEEPGREEN";
        default:                           return "Unknown";
        }
    }
} // namespace cmap